// Command seed prepares the SQLite store used by the indexarr simulation.
//
// It runs before indexarr starts: it sets public_url, enables torrent fetching
// and synchronises the built-in catalog. The API key is generated by indexarr
// itself on first start; -print-key reads it back afterwards for scripts that
// cannot parse the log.
package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/buzzqw/indexarr/internal/catalog"
	"github.com/buzzqw/indexarr/internal/store"
)

func main() {
	dbPath := flag.String("db", "", "path to indexarr.db")
	publicURL := flag.String("public-url", "", "value for the public_url setting")
	printKey := flag.Bool("print-key", false, "print the stored Torznab API key and exit")
	flag.Parse()

	if strings.TrimSpace(*dbPath) == "" {
		fmt.Fprintln(os.Stderr, "seed: -db is required")
		os.Exit(2)
	}

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	st, err := store.Open(*dbPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "seed: open store: %v\n", err)
		os.Exit(1)
	}
	defer st.Close()

	settings, err := st.LoadSettings(ctx)
	if err != nil {
		fmt.Fprintf(os.Stderr, "seed: load settings: %v\n", err)
		os.Exit(1)
	}

	if *printKey {
		if strings.TrimSpace(settings.APIKey) == "" {
			fmt.Fprintln(os.Stderr, "seed: API key is not configured yet")
			os.Exit(1)
		}
		fmt.Println(settings.APIKey)
		return
	}

	if value := strings.TrimSpace(*publicURL); value != "" {
		settings.PublicURL = strings.TrimRight(value, "/")
	}
	settings.FetchTorrents = true
	if settings.DefaultIntervalSeconds < 60 {
		settings.DefaultIntervalSeconds = 3600
	}
	if err := st.SaveSettings(ctx, settings); err != nil {
		fmt.Fprintf(os.Stderr, "seed: save settings: %v\n", err)
		os.Exit(1)
	}

	written, err := catalog.Sync(ctx, st)
	if err != nil {
		fmt.Fprintf(os.Stderr, "seed: sync catalog: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("seed: database=%s public_url=%s catalog_definitions=%d\n",
		*dbPath, settings.PublicURL, written)
}
